import{_ as l,o as i,c as e,ag as t}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 20 章：日常生活案例——用一张对比表帮家人选净水器","description":"从零散商品信息到「可决策对比表」的生活案例；重点演示多来源核对、口径统一与「人做最终决定」。","frontmatter":{"title":"第 20 章：日常生活案例——用一张对比表帮家人选净水器","description":"从零散商品信息到「可决策对比表」的生活案例；重点演示多来源核对、口径统一与「人做最终决定」。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/20-life-case.md","filePath":"guide/20-life-case.md","lastUpdated":null}'),o={name:"guide/20-life-case.md"};function r(n,a,s,d,h,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="第-20-章-日常生活案例——用一张对比表帮家人选净水器" tabindex="-1">第 20 章：日常生活案例——用一张对比表帮家人选净水器 <a class="header-anchor" href="#第-20-章-日常生活案例——用一张对比表帮家人选净水器" aria-label="Permalink to &quot;第 20 章：日常生活案例——用一张对比表帮家人选净水器&quot;">​</a></h1><h2 id="案例摘要" tabindex="-1">案例摘要 <a class="header-anchor" href="#案例摘要" aria-label="Permalink to &quot;案例摘要&quot;">​</a></h2><ul><li>使用场景：生活（选购对比）</li><li>使用者基础：零基础可复现</li><li>使用的 Agent：任意桌面 Agent（托管路径均可）</li><li>完成时间：约 30–40 分钟</li><li>风险等级：低—中（涉及付款，最终购买必须人工）</li><li>最终交付物：一张净水器对比表 + 个人决策清单</li></ul><h2 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h2><p>家里想买一台净水器，家人在三个电商平台收藏了五六款商品，参数截图、客服回答、评论区截图散落各处。家人越看越乱：「这款滤芯贵不贵」「这款要不要装橱下」「促销价是不是真的便宜」。需要一个能直接支撑决策的对比表，而不是又一份「参数大全」。</p><h2 id="原始需求" tabindex="-1">原始需求 <a class="header-anchor" href="#原始需求" aria-label="Permalink to &quot;原始需求&quot;">​</a></h2><blockquote><p>「帮我看看这几款净水器哪个好，我要买一台。」</p></blockquote><p>（模糊版：没有列出具体型号、没说要对比什么维度、没说预算。）</p><h2 id="任务判断" tabindex="-1">任务判断 <a class="header-anchor" href="#任务判断" aria-label="Permalink to &quot;任务判断&quot;">​</a></h2><ul><li>为什么适合 Agent：材料整理与对比生成是强项；但<strong>选购决策必须人做</strong>；</li><li>交给 Agent：收集/整理参数、统一口径、生成对比表、标注差异与待核实项；</li><li>人必须做的：确定预算与核心需求、核对价格与促销真伪、最终拍板与付款。</li></ul><h2 id="整理后的任务卡" tabindex="-1">整理后的任务卡 <a class="header-anchor" href="#整理后的任务卡" aria-label="Permalink to &quot;整理后的任务卡&quot;">​</a></h2><ul><li><strong>目标</strong>：把 5 款净水器整理成一张对比表，供家庭 10 分钟看完做决定；</li><li><strong>上下文</strong>：三口之家、厨房有橱下空间、预算 ¥2,000 内、关注「滤芯年成本」「换芯难度」「占地」；</li><li><strong>输入材料</strong>：<code>shopping/</code> 下 5 个文件（每款一张参数截图或商品链接要点）；<strong>说明：价格以官方页面为准，截图时间是 X 月 X 日；</strong></li><li><strong>范围与约束</strong>：不联网搜索（或：允许联网但只参考官方页面）；不编造参数；价格标注「截图价/需核实」；输出对比表到 <code>output/</code>；</li><li><strong>交付物</strong>：<code>output/water-filter-compare.md</code>（对比表 + 差异点 + 待核实清单）；</li><li><strong>验收标准</strong>：覆盖全部 5 款；列含价格/滤芯年成本/换芯难度/占地/噪音；每项数据标来源；无法确认的标「未核实」。</li></ul><h2 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h2><ol><li>把截图/链接存进 <code>shopping/</code>；</li><li>发送任务卡（含口径：预算、核心需求）；</li><li>Agent 生成对比表初稿；</li><li>人对价格列逐项对照官方页面核实。</li></ol><h2 id="出现的问题" tabindex="-1">出现的问题 <a class="header-anchor" href="#出现的问题" aria-label="Permalink to &quot;出现的问题&quot;">​</a></h2><ul><li>Agent 把两款的「促销价」当成「常态价」——<strong>价格过时/口径不一</strong>；</li><li>一款的「滤芯年成本」没有官方数字，Agent 打算自己估算——<strong>编造风险</strong>；</li><li>评论区截图里的一句话被 Agent 当成参数引用——<strong>来源不可靠</strong>。</li></ul><h2 id="修正与判断" tabindex="-1">修正与判断 <a class="header-anchor" href="#修正与判断" aria-label="Permalink to &quot;修正与判断&quot;">​</a></h2><ul><li>价格列统一改为「当前官方页面价 + 截图日期」，促销价单独一列；</li><li>规则更新：「没有官方数字的，标『未核实』，禁止估算」；</li><li>删除评论区引用，只保留官方参数页来源。</li></ul><h2 id="最终结果与验收" tabindex="-1">最终结果与验收 <a class="header-anchor" href="#最终结果与验收" aria-label="Permalink to &quot;最终结果与验收&quot;">​</a></h2><ul><li>对比表 5 行 × 8 列，覆盖全部模型；</li><li>价格与滤芯成本全部标了来源与日期；</li><li>3 个「未核实」项列在表尾，家人到官方页确认后完成决策；</li><li>最终购买（付款）由家人人工完成。</li></ul><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ul><li>Agent 做得好的：参数整理、口径统一、对比表结构；</li><li>人必须介入的：价格真伪、预算拍板、付款；</li><li>下次可省略：不用每次重写任务卡——存成「选购对比」模板（第 12 章）；</li><li>可沉淀：<strong>选购对比模板</strong>（目标/口径/来源标注/未核实列），下次买冰箱、保险、课程都能复用。</li></ul><h2 id="给新手的最小版本" tabindex="-1">给新手的最小版本 <a class="header-anchor" href="#给新手的最小版本" aria-label="Permalink to &quot;给新手的最小版本&quot;">​</a></h2><p>20 分钟复现：选一个你最近要买/要比的东西（哪怕是「3 款耳机」）→ 收集 3 个信息源（截图或链接）→ 按任务卡发一次 → 验收重点：<strong>每个数字有没有来源、有没有「未核实」标注、最终决定是不是你做的。</strong></p>',24)])])}const p=l(o,[["render",r]]);export{g as __pageData,p as default};
